from pathlib import Path

# SessionPanel: scenario-aware instructor launch wizard.
p = Path('src/components/SessionPanel.tsx')
t = p.read_text()
repls = [
("import type { PatientSettings, VentilatorSettings } from '../simulation/types'\n", "import type { PatientSettings, VentilatorSettings } from '../simulation/types'\nimport {\n  getInstructorAccount,\n  listInstructorPresets,\n  type InstructorPresetRow,\n  type InstructorScenarioSnapshot,\n} from '../instructorAccount'\n"),
("  recoverableCandidate?: { sessionKey: string; displayName: string; expiresAt: string } | null\n  onStartInstructor: () => Promise<void>\n", "  recoverableCandidate?: { sessionKey: string; displayName: string; expiresAt: string } | null\n  currentScenario: InstructorScenarioSnapshot\n  onLoadScenario: (scenario: InstructorScenarioSnapshot) => void\n  onStartInstructor: (scenario?: InstructorScenarioSnapshot) => Promise<void>\n"),
("  recoverableInstructor,\n  recoverableCandidate,\n  onStartInstructor,\n", "  recoverableInstructor,\n  recoverableCandidate,\n  currentScenario,\n  onLoadScenario,\n  onStartInstructor,\n"),
("  const [sessionControlsExpanded, setSessionControlsExpanded] = useState(false)\n  const [now, setNow] = useState(() => Date.now())\n", "  const [sessionControlsExpanded, setSessionControlsExpanded] = useState(false)\n  const [now, setNow] = useState(() => Date.now())\n  const [startWizardOpen, setStartWizardOpen] = useState(false)\n  const [startSource, setStartSource] = useState<'current' | 'scenario'>('current')\n  const [startPresets, setStartPresets] = useState<InstructorPresetRow[]>([])\n  const [selectedStartPresetId, setSelectedStartPresetId] = useState('')\n  const [startPresetsBusy, setStartPresetsBusy] = useState(false)\n  const [startPresetMessage, setStartPresetMessage] = useState<string | null>(null)\n"),
]
for old, new in repls:
    if old not in t: raise SystemExit(f'SessionPanel anchor missing: {old[:80]!r}')
    t = t.replace(old, new, 1)
anchor = "  const candidateJoinUrl = useMemo(() => {\n    if (!session?.session_key || typeof window === 'undefined') return ''\n    const url = new URL(window.location.href)\n    url.search = ''\n    url.hash = ''\n    url.searchParams.set('session', session.session_key)\n    return url.toString()\n  }, [session?.session_key])\n\n"
extra = """  const selectedStartPreset = useMemo(\n    () => startPresets.find((preset) => preset.id === selectedStartPresetId) ?? null,\n    [startPresets, selectedStartPresetId],\n  )\n\n  const openInstructorStart = async () => {\n    setStartWizardOpen(true)\n    setStartSource('current')\n    setSelectedStartPresetId('')\n    setStartPresets([])\n    setStartPresetMessage(null)\n    setStartPresetsBusy(true)\n    try {\n      const account = await getInstructorAccount()\n      if (!account) {\n        setStartPresetMessage('Current setup is ready. Sign in to the instructor cloud account to start from a saved scenario.')\n        return\n      }\n      const presets = (await listInstructorPresets()).filter((preset) => (preset.scenario.kind ?? 'static') === 'static')\n      setStartPresets(presets)\n      if (presets.length) setSelectedStartPresetId(presets[0].id)\n      else setStartPresetMessage('No static scenarios are saved yet. You can start from the current setup.')\n    } catch (cause) {\n      setStartPresetMessage(cause instanceof Error ? cause.message : 'Unable to load saved scenarios.')\n    } finally {\n      setStartPresetsBusy(false)\n    }\n  }\n\n  const startInstructorFromWizard = async () => {\n    const scenario = startSource === 'scenario' ? selectedStartPreset?.scenario : undefined\n    if (startSource === 'scenario' && !scenario) return\n    await onStartInstructor(scenario)\n  }\n\n  const loadSelectedScenarioIntoStandalone = () => {\n    if (!selectedStartPreset) return\n    onLoadScenario(selectedStartPreset.scenario)\n    setStartWizardOpen(false)\n    setStartSource('current')\n  }\n\n  const summaryFor = (scenario: InstructorScenarioSnapshot) => [\n    scenario.ventilator.mode,\n    `FiO₂ ${Math.round(scenario.ventilator.fio2 * 100)}%`,\n    `PEEP ${scenario.ventilator.peep}`,\n    `RR ${scenario.ventilator.rate}`,\n    `C ${scenario.patient.compliance.toFixed(0)}`,\n    `R ${scenario.patient.resistance.toFixed(0)}`,\n    `Shunt ${Math.round((scenario.patient.shuntFraction ?? 0.03) * 100)}%`,\n  ]\n\n"""
if anchor not in t: raise SystemExit('candidateJoinUrl anchor missing')
t = t.replace(anchor, anchor + extra, 1)
old = """        {!joinMode ? (\n          <div className=\"session-launch-actions\">\n            <button type=\"button\" className=\"session-primary-button\" disabled={connection === 'connecting'} onClick={() => void onStartInstructor()}>\n              Start instructor session\n            </button>\n            <button type=\"button\" className=\"session-secondary-button\" onClick={() => setJoinMode(true)}>Join as candidate</button>\n            {recoverableCandidate && onResumeCandidate && (\n              <button type=\"button\" className=\"session-secondary-button\" disabled={connection === 'connecting'} onClick={() => void onResumeCandidate()}>Rejoin candidate {recoverableCandidate.sessionKey}</button>\n            )}\n            {recoverableInstructor && onResumeInstructor && (\n              <button type=\"button\" className=\"session-secondary-button\" onClick={() => void onResumeInstructor(recoverableInstructor.sessionId)}>Rejoin instructor {recoverableInstructor.sessionKey}</button>\n            )}\n          </div>\n        ) : (\n"""
new = """        {!joinMode ? (\n          startWizardOpen ? (\n            <div className=\"session-start-wizard\">\n              <div className=\"session-start-wizard-heading\">\n                <div><span>Instructor session</span><strong>Choose starting state</strong></div>\n                <button type=\"button\" className=\"session-start-close\" onClick={() => setStartWizardOpen(false)} aria-label=\"Close session setup\">×</button>\n              </div>\n              <div className=\"session-start-source-tabs\" role=\"tablist\" aria-label=\"Instructor session starting state\">\n                <button type=\"button\" className={startSource === 'current' ? 'selected' : ''} onClick={() => setStartSource('current')}>Current setup</button>\n                <button type=\"button\" className={startSource === 'scenario' ? 'selected' : ''} disabled={startPresetsBusy || !startPresets.length} onClick={() => setStartSource('scenario')}>Saved scenario</button>\n              </div>\n              {startSource === 'current' ? (\n                <div className=\"session-start-current-card\">\n                  <span>Current standalone setup</span>\n                  <strong>{currentScenario.ventilator.mode} · FiO₂ {Math.round(currentScenario.ventilator.fio2 * 100)}% · PEEP {currentScenario.ventilator.peep}</strong>\n                  <div className=\"session-start-summary-chips\">{summaryFor(currentScenario).map((item) => <em key={item}>{item}</em>)}</div>\n                  <small>You can configure the patient and ventilator in standalone mode before opening the room.</small>\n                </div>\n              ) : (\n                <div className=\"session-start-scenarios\">\n                  <div className=\"session-start-scenario-list\">\n                    {startPresets.map((preset) => (\n                      <button type=\"button\" key={preset.id} className={`session-start-scenario-option ${selectedStartPresetId === preset.id ? 'selected' : ''}`} onClick={() => setSelectedStartPresetId(preset.id)}>\n                        <strong>{preset.name}</strong>\n                        <small>{preset.scenario.description || 'Static scenario'}</small>\n                      </button>\n                    ))}\n                  </div>\n                  {selectedStartPreset && (\n                    <div className=\"session-start-scenario-preview\">\n                      <span>Selected scenario</span>\n                      <strong>{selectedStartPreset.name}</strong>\n                      {selectedStartPreset.scenario.description && <p>{selectedStartPreset.scenario.description}</p>}\n                      <div className=\"session-start-summary-chips\">{summaryFor(selectedStartPreset.scenario).map((item) => <em key={item}>{item}</em>)}</div>\n                      <button type=\"button\" className=\"session-secondary-button\" onClick={loadSelectedScenarioIntoStandalone}>Load into standalone to adjust</button>\n                    </div>\n                  )}\n                </div>\n              )}\n              {startPresetsBusy && <div className=\"session-start-note\">Loading saved scenarios…</div>}\n              {startPresetMessage && <div className=\"session-start-note\">{startPresetMessage}</div>}\n              <div className=\"session-start-actions\">\n                <button type=\"button\" className=\"session-primary-button\" disabled={connection === 'connecting' || (startSource === 'scenario' && !selectedStartPreset)} onClick={() => void startInstructorFromWizard()}>\n                  {startSource === 'scenario' && selectedStartPreset ? `Start with ${selectedStartPreset.name}` : 'Start with current setup'}\n                </button>\n                <button type=\"button\" className=\"session-secondary-button\" onClick={() => setStartWizardOpen(false)}>Cancel</button>\n              </div>\n            </div>\n          ) : (\n            <div className=\"session-launch-actions\">\n              <button type=\"button\" className=\"session-primary-button\" disabled={connection === 'connecting'} onClick={() => void openInstructorStart()}>Start instructor session</button>\n              <button type=\"button\" className=\"session-secondary-button\" onClick={() => setJoinMode(true)}>Join as candidate</button>\n              {recoverableCandidate && onResumeCandidate && (<button type=\"button\" className=\"session-secondary-button\" disabled={connection === 'connecting'} onClick={() => void onResumeCandidate()}>Rejoin candidate {recoverableCandidate.sessionKey}</button>)}\n              {recoverableInstructor && onResumeInstructor && (<button type=\"button\" className=\"session-secondary-button\" onClick={() => void onResumeInstructor(recoverableInstructor.sessionId)}>Rejoin instructor {recoverableInstructor.sessionKey}</button>)}\n            </div>\n          )\n        ) : (\n"""
if old not in t: raise SystemExit('standalone launch block missing')
t = t.replace(old, new, 1)
p.write_text(t)

# useTeachingSession: direct snapshot input prevents React state timing races.
p = Path('src/session/useTeachingSession.ts')
t = p.read_text()
anchor = "interface UseTeachingSessionArgs {\n"
if anchor not in t: raise SystemExit('UseTeachingSessionArgs missing')
t = t.replace(anchor, "export interface InstructorSessionInitialState {\n  patient: PatientSettings\n  ventilator: VentilatorSettings\n  alarmLimits: AlarmLimits\n  patientTransitionSeconds: number\n}\n\n" + anchor, 1)
for old, new in [
("  const alarmLimitsRef = useRef(alarmLimits)\n  const alarmLevelRef = useRef<CandidateAlarmLevel>(candidateAlarmLevel)\n", "  const alarmLimitsRef = useRef(alarmLimits)\n  const patientTransitionSecondsRef = useRef(patientTransitionSeconds)\n  const alarmLevelRef = useRef<CandidateAlarmLevel>(candidateAlarmLevel)\n"),
("  useEffect(() => { alarmLimitsRef.current = alarmLimits }, [alarmLimits])\n  useEffect(() => { alarmLevelRef.current = candidateAlarmLevel }, [candidateAlarmLevel])\n", "  useEffect(() => { alarmLimitsRef.current = alarmLimits }, [alarmLimits])\n  useEffect(() => { patientTransitionSecondsRef.current = patientTransitionSeconds }, [patientTransitionSeconds])\n  useEffect(() => { alarmLevelRef.current = candidateAlarmLevel }, [candidateAlarmLevel])\n"),
]:
    if old not in t: raise SystemExit('useTeachingSession ref anchor missing')
    t = t.replace(old, new, 1)
old = """  const startInstructor = async () => {\n    setConnection('connecting')\n    setError(null)\n    try {\n      const created = await createTeachingSession(patient, ventilator, alarmLimits)\n      roleRef.current = 'instructor'\n      setRole('instructor')\n      let row = await fetchTeachingSession(created.sessionId)\n"""
new = """  const startInstructor = async (initial?: InstructorSessionInitialState) => {\n    setConnection('connecting')\n    setError(null)\n    const startingPatient = initial?.patient ?? patientRef.current\n    const startingVentilator = initial?.ventilator ?? ventilatorRef.current\n    const startingAlarmLimits = initial?.alarmLimits ?? alarmLimitsRef.current\n    const startingTransitionSeconds = initial?.patientTransitionSeconds ?? patientTransitionSecondsRef.current\n    try {\n      const created = await createTeachingSession(startingPatient, startingVentilator, startingAlarmLimits)\n      roleRef.current = 'instructor'\n      setRole('instructor')\n      let row = await fetchTeachingSession(created.sessionId)\n      const transitionMs = Math.max(0, Math.round(startingTransitionSeconds * 1000))\n      if (Number(row.transition_ms ?? 0) !== transitionMs) {\n        row = await updateTeachingSession(created.sessionId, { transition_ms: transitionMs })\n      }\n"""
if old not in t: raise SystemExit('startInstructor block missing')
t = t.replace(old, new, 1)
p.write_text(t)

# App wiring.
p = Path('src/App.tsx')
t = p.read_text()
anchor = """  const loadInstructorScenario = (scenario: InstructorScenarioSnapshot) => {\n    setVentilator({ ...scenario.ventilator })\n    setPatient({ ...scenario.patient })\n    setAlarmLimits({ ...scenario.alarmLimits })\n    setPatientTransitionSeconds(scenario.patientTransitionSeconds)\n    setWaveformDisplay({ ...scenario.waveformDisplay })\n  }\n\n"""
if anchor not in t: raise SystemExit('loadInstructorScenario missing')
t = t.replace(anchor, anchor + """  const startInstructorSession = async (scenario?: InstructorScenarioSnapshot) => {\n    if (scenario) {\n      loadInstructorScenario(scenario)\n      await teachingSession.startInstructor({\n        patient: scenario.patient,\n        ventilator: scenario.ventilator,\n        alarmLimits: scenario.alarmLimits,\n        patientTransitionSeconds: scenario.patientTransitionSeconds,\n      })\n      return\n    }\n    await teachingSession.startInstructor()\n  }\n\n""", 1)
old = "            recoverableCandidate={teachingSession.recoverableCandidate}\n            onStartInstructor={teachingSession.startInstructor}\n"
new = "            recoverableCandidate={teachingSession.recoverableCandidate}\n            currentScenario={currentInstructorScenario}\n            onLoadScenario={loadInstructorScenario}\n            onStartInstructor={startInstructorSession}\n"
if old not in t: raise SystemExit('SessionPanel App wiring missing')
t = t.replace(old, new, 1)
p.write_text(t)

# Compact launch styles.
p = Path('src/session.css')
t = p.read_text()
t += '''\n\n/* v0.63 instructor scenario-aware session launch */\n.session-start-wizard { display: grid; gap: 12px; padding: 12px; border: 1px solid #324851; border-radius: 12px; background: #0a1419; }\n.session-start-wizard-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }\n.session-start-wizard-heading span { display: block; color: #6f8993; font-size: 9px; letter-spacing: .1em; text-transform: uppercase; }\n.session-start-wizard-heading strong { display: block; margin-top: 2px; color: #edf6f8; font-size: 14px; }\n.session-start-close { width: 30px; height: 30px; padding: 0; display: grid; place-items: center; border-radius: 50%; font-size: 20px; line-height: 1; }\n.session-start-source-tabs { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }\n.session-start-source-tabs button { min-height: 36px; font-size: 10px; }\n.session-start-source-tabs button.selected { color: #e7f9ff; border-color: #5eb9d7; background: #173746; }\n.session-start-current-card, .session-start-scenario-preview { display: grid; gap: 7px; padding: 11px; border: 1px solid #293e47; border-radius: 9px; background: #0c171c; }\n.session-start-current-card > span, .session-start-scenario-preview > span { color: #6f8993; font-size: 9px; letter-spacing: .08em; text-transform: uppercase; }\n.session-start-current-card > strong, .session-start-scenario-preview > strong { color: #e2f0f4; font-size: 12px; }\n.session-start-current-card > small { color: #81959e; font-size: 10px; line-height: 1.4; }\n.session-start-summary-chips { display: flex; flex-wrap: wrap; gap: 5px; }\n.session-start-summary-chips em { padding: 3px 6px; border: 1px solid #304650; border-radius: 999px; background: #101f26; color: #9eb4bc; font-size: 9px; font-style: normal; white-space: nowrap; }\n.session-start-scenarios { display: grid; gap: 9px; }\n.session-start-scenario-list { display: grid; gap: 6px; max-height: 190px; overflow-y: auto; padding-right: 2px; }\n.session-start-scenario-option { display: grid; gap: 3px; width: 100%; padding: 9px 10px; text-align: left; border-radius: 8px; background: #0c151a; border-color: #2d3e47; }\n.session-start-scenario-option strong { color: #dce9ed; font-size: 11px; }\n.session-start-scenario-option small { color: #758a93; font-size: 9px; line-height: 1.35; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.session-start-scenario-option.selected { border-color: #56abc7; background: #122b36; box-shadow: inset 0 0 0 1px rgba(86,171,199,.12); }\n.session-start-scenario-preview p { margin: 0; color: #8da0a8; font-size: 10px; line-height: 1.4; }\n.session-start-scenario-preview .session-secondary-button { margin-top: 2px; justify-self: start; }\n.session-start-note { padding: 8px 9px; border: 1px solid #33434a; border-radius: 8px; background: #111a1e; color: #91a4ab; font-size: 10px; line-height: 1.4; }\n.session-start-actions { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 7px; }\n@media (max-width: 620px) { .session-start-actions { grid-template-columns: 1fr; } }\n'''
p.write_text(t)

# Version bump.
for p in Path('src').rglob('*'):
    if p.suffix not in {'.ts', '.tsx'}: continue
    t = p.read_text()
    u = t.replace('v0.62', 'v0.63').replace("appVersion: '0.62'", "appVersion: '0.63'")
    if u != t: p.write_text(u)

print('v0.63 patch applied')
